/**
 * Abugram: what this account may use, as the Abugram admin set it (relay /access): ghost mode for the accounts
 * allowed it, the admin page link for admins. Everyone else gets neither; their ghost switches have no effect.
 */
import {createRoot, createSignal} from 'solid-js';
import rootScope from '@lib/rootScope';
import {setAppSettings, appSettings} from '@stores/appSettings';

export type AbugramAccess = {ghost: boolean, admin: boolean};

const [access, setAccess] = createRoot(() => createSignal<AbugramAccess>({ghost: false, admin: false}));
export const abugramAccess = access;

export const ABUGRAM_ADMIN_URL = 'https://abdulaziz0196.github.io/tashlanov.ru/abugram/admin.html';

function relayBase(): string {
  const relay: string = import.meta.env.VITE_ABUGRAM_RELAY || '';
  return relay.replace(/^wss:/i, 'https:').replace(/\/+$/, '');
}

export async function loadAbugramAccess() {
  const base = relayBase();
  const uid = rootScope.myId ? rootScope.myId.toUserId() : 0;
  if(!base || !uid) return;
  // * counted as an Abugram user with the app's version; every start of the app is one visit (the relay keeps only a hash of the ID)
  const version: string = import.meta.env.VITE_ABUGRAM_VERSION || '';
  let said: string;
  try {
    said = sessionStorage.getItem('abugram.hello');
  } catch(err) {}
  if(said !== String(uid)) {
    fetch(base + '/hello', {method: 'POST', body: JSON.stringify({uid, platform: 'web', version}), keepalive: true}).then(() => {
      try {
        sessionStorage.setItem('abugram.hello', String(uid));
      } catch(err) {}
    }).catch(() => {});
  }

  try {
    const response = await fetch(base + '/access?uid=' + uid, {cache: 'no-store'});
    const result = await response.json();
    const value: AbugramAccess = {ghost: !!result.ghost, admin: !!result.admin};
    setAccess(value);
    checkAbugramGate(base, uid, !!result.pro || !!result.admin);
    // * the request filter (in the MTProto worker) honours the ghost switches only while this is set
    if(!!appSettings.abugram?.ghostAllowed !== value.ghost) {
      if(appSettings.abugram) setAppSettings('abugram', 'ghostAllowed', value.ghost);
      else setAppSettings('abugram', {ghostAllowed: value.ghost});
    }
  } catch(err) {}
}

let gateShown = false;

/**
 * What the Abugram admin set in the relay's /config: in paid mode an account without a paid period (and not admin) gets a
 * full-screen notice with a button to the Abugram site. Off while the app is free: nothing is shown.
 */
async function checkAbugramGate(base: string, uid: number, pro: boolean) {
  if(gateShown || pro) return;
  try {
    const config = await (await fetch(base + '/config', {cache: 'no-store'})).json();
    if(!config.paid) return;
    gateShown = true;
    const box = document.createElement('div');
    box.style.cssText = 'position:fixed;inset:0;z-index:100000;background:var(--surface-color,#fff);color:var(--primary-text-color,#000);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:32px;text-align:center;font-size:18px';
    const title = document.createElement('div');
    title.style.cssText = 'font-size:24px;font-weight:700';
    title.textContent = config.payTitle || 'Obuna kerak';
    const text = document.createElement('div');
    text.textContent = config.payMessage || '';
    const button = document.createElement('a');
    button.textContent = 'Ochish';
    button.href = 'https://abdulaziz0196.github.io/tashlanov.ru/abugram/pay.html?uid=' + uid;
    button.target = '_blank';
    button.rel = 'noopener';
    button.style.cssText = 'padding:12px 28px;border-radius:12px;background:var(--primary-color,#6A5CFF);color:#fff;text-decoration:none;font-weight:600';
    box.append(title, text, button);
    document.body.append(box);
    // while the notice is up: look every 15 seconds whether the account has paid, or paid mode was switched off
    const timer = setInterval(async() => {
      try {
        const access = await (await fetch(base + '/access?uid=' + uid, {cache: 'no-store'})).json();
        const now = await (await fetch(base + '/config', {cache: 'no-store'})).json();
        if(access.pro || access.admin || !now.paid) {
          clearInterval(timer);
          box.remove();
          gateShown = false;
        }
      } catch(err) {}
    }, 15000);
  } catch(err) {}
}
